        +costo(): double
    }
    class PiazzolaBase {
        -mq: double
        +costo(): double
    }
    class Accessorio {
        <<abstract>>
        -piazzola: Piazzola
    }
    class Corrente {
        +costo(): double
    }
    class Tettoia {
        +costo(): double
